$ErrorActionPreference='Stop'
$root=Join-Path ([IO.Path]::GetTempPath()) ('maya-candidate-'+[guid]::NewGuid().ToString('N'));$ao=Join-Path $root 'AgentOrchestration';New-Item $ao -ItemType Directory -Force|Out-Null
Copy-Item (Join-Path $PSScriptRoot '*') $ao -Recurse -Force
$repo=$root;$bin=Join-Path $repo 'bin\Release\net8.0-windows';New-Item $bin -ItemType Directory -Force|Out-Null
$dll=Join-Path $bin 'Repato.Revit.dll';[IO.File]::WriteAllText($dll,'synthetic authenticated build');$manifest=Join-Path $repo 'Repato.addin';Set-Content $manifest '<RevitAddIns />'
Import-Module (Join-Path $ao 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $ao 'Repato.Deployment.v4.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $ao 'Repato.AgentOrchestration.psm1') -Force -WarningAction SilentlyContinue
$store=Join-Path $root 'store';$b=New-MayaQaBootstrap -StoreRoot $store -QaWorkflowId 'create-plan-views-v1' -RunId 'synthetic-run';New-MayaQaBuildRequest -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId 'create-plan-views-v1' -UserRequest 'Create Plan Views' -SourceBranch synthetic -ProjectPath synthetic.csproj|Out-Null;$w=Get-DeployWorkflow $store $b.TaskId $b.WorkflowId;$t=Find-RepatoTask (Read-RepatoTaskStore $store) $b.TaskId;$hash=(Get-FileHash $dll -Algorithm SHA256).Hash;$mh=(Get-FileHash $manifest -Algorithm SHA256).Hash;$commit='1234567890abcdef1234567890abcdef12345678'
Invoke-RepatoWorkflowMutation $store $b.TaskId $b.WorkflowId $w.workflowRevision $t.revision {param($x)$x|Add-Member NoteProperty qaBuildStatus 'succeeded' -Force;$x|Add-Member NoteProperty qaBuildEvidence ([pscustomobject]@{BuildRequestId=$x.qaBuildRequest.BuildRequestId;SourceCommit=$commit;ArtifactPath=$dll;ArtifactSha256=$hash;ManifestPath=$manifest;ManifestSha256=$mh}) -Force;$x}|Out-Null
$passed=0;function Check([bool]$ok,[string]$name){if(!$ok){throw "FAILED: $name"};$script:passed++};function Reject([scriptblock]$x,[string]$name){$bad=$false;try{&$x|Out-Null}catch{$bad=$true};Check $bad $name}
try {
  $r=New-MayaQaCanonicalCandidate $store $b.TaskId $b.WorkflowId 'create-plan-views-v1' 'create-plan-views-v1';$v=Test-MayaQaFrozenCandidate $r.CandidateDirectory $r.CandidateDllPath $hash $commit 'create-plan-views-v1'
  Check ($r.CandidateSha256 -ceq $hash) 'candidate hash equals build hash';Check ($r.CandidateSourceCommit -ceq $commit) 'source commit is build-bound';Check ((Get-Content $r.CandidateProvenancePath -Raw|ConvertFrom-Json).TaskId -ceq $b.TaskId) 'provenance linkage';Check ($v.ArtifactSha256 -ceq $hash) 'frozen validator accepts candidate';Check ($r.Reused -eq $false) 'candidate created'
  $r2=New-MayaQaCanonicalCandidate $store $b.TaskId $b.WorkflowId 'create-plan-views-v1' 'create-plan-views-v1';Check ($r2.Reused) 'identical candidate reused';Reject {New-MayaQaCanonicalCandidate $store $b.TaskId $b.WorkflowId 'create-plan-views-v1' 'wrong-test'} 'caller test identity cannot alter canonical workflow';$old=[IO.File]::ReadAllBytes($r.CandidateDllPath);$p=Get-Content $r.CandidateProvenancePath -Raw|ConvertFrom-Json;$p.SourceCommit='f'*40;$p|ConvertTo-Json|Set-Content $r.CandidateProvenancePath;Reject {New-MayaQaCanonicalCandidate $store $b.TaskId $b.WorkflowId 'create-plan-views-v1' 'create-plan-views-v1'} 'conflicting candidate rejected';[IO.File]::WriteAllBytes($r.CandidateDllPath,$old)
  [pscustomobject]@{Status='PASS';AssertionsPassed=$passed;AssertionsFailed=0;RealTaskMutated=$false;RealBuildPerformed=$false;RealCandidateCreated=$false}|ConvertTo-Json -Compress
} finally {Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue}
